import AppKit
import Testing
@testable import SezishApp

/// The dictated text lands on the clipboard as one item carrying the
/// nspasteboard.org auto-generated marker; ⌘V is posted after it.
@MainActor
struct PasteInserterTests {
    @Test func writesTheTextWithTheMarkerThenPastes() async throws {
        let board = NSPasteboard(name: .init("sezish-test-\(UUID().uuidString)"))
        defer { board.releaseGlobally() }
        var pastes = 0
        let inserter = PasteInserter(pasteboard: board, paste: { pastes += 1 })
        // Secure Input may be on while the tests run; the clipboard is written either way.
        try? await inserter.insert("привет")
        #expect(board.string(forType: .string) == "привет")
        #expect(board.pasteboardItems?.count == 1)
        #expect(board.types?.contains(PasteInserter.autoGeneratedType) == true)
        #expect(pastes <= 1)
    }
}
